import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { makeCommsChannel, sendAMessage, sendForAReply } from "@/core/frameMessaging.ts";

describe("sendAMessage", () => {

  beforeEach(() => { vi.useFakeTimers(); });
  afterEach(() => { vi.useRealTimers(); });

  it("holds the message until the readiness condition becomes true, then sends it", async () => {
    let ready = false;
    const sent: Array<object> = [];
    const send = sendAMessage(() => ready, (m: object) => { sent.push(m); });

    const pending = send({ type: "hello" });
    await vi.advanceTimersByTimeAsync(500);
    expect(sent).toEqual([]);

    ready = true;
    await vi.advanceTimersByTimeAsync(100);
    await pending;
    expect(sent).toEqual([{ type: "hello" }]);
  });

  it("sends immediately when the condition is already true", async () => {
    const sent: Array<object> = [];
    await sendAMessage(() => true, (m: object) => { sent.push(m); })({ type: "now" });
    expect(sent).toEqual([{ type: "now" }]);
  });

});

describe("sendForAReply", () => {

  beforeEach(() => { vi.useFakeTimers(); });
  afterEach(() => { vi.useRealTimers(); });

  it("resolves with whatever the other side posts back on the supplied port", async () => {
    const ask = sendForAReply(() => true, (_m: object, port: MessagePort) => {
      port.postMessage({ answer: 42 });
    });
    const reply = ask({ type: "question" });
    await vi.advanceTimersByTimeAsync(10);
    // Real MessageChannel delivery is asynchronous outside the fake clock
    vi.useRealTimers();
    await expect(reply).resolves.toEqual({ answer: 42 });
  });

  it("rejects with a timeout error if nobody answers within five seconds", async () => {
    const ask   = sendForAReply(() => true, () => {});
    const reply = ask({ type: "question" });
    const check = expect(reply).rejects.toThrow(/timed out/i);
    await vi.advanceTimersByTimeAsync(5001);
    await check;
  });

});

describe("makeCommsChannel", () => {

  it("delivers a message to the other port and resolves with the reply", async () => {
    const [theirPort, sender] = makeCommsChannel();
    theirPort.onmessage = (e: MessageEvent<{ n: number }>): void => { theirPort.postMessage({ doubled: e.data.n * 2 }); };
    await expect(sender({ n: 21 }, true)).resolves.toEqual({ doubled: 42 });
    theirPort.close();
  });

  const withDeadline = <T,>(p: Promise<T>): Promise<T> =>
    Promise.race([p, new Promise<T>((_, reject) => setTimeout(() => { reject(new Error("never resolved")); }, 300))]);

  it("keeps concurrent requests apart: each caller gets a reply, in order", async () => {
    const [theirPort, sender] = makeCommsChannel();
    theirPort.onmessage = (e: MessageEvent<{ n: number }>): void => { theirPort.postMessage({ echo: e.data.n }); };

    const [a, b] = await Promise.all([withDeadline(sender({ n: 1 }, true)), withDeadline(sender({ n: 2 }, true))]);
    expect(a).toEqual({ echo: 1 });
    expect(b).toEqual({ echo: 2 });
    theirPort.close();
  });

  it("does not hand a reply meant for another request to a caller whose predicate rejects it", async () => {
    const [theirPort, sender] = makeCommsChannel();
    theirPort.onmessage = (e: MessageEvent<{ type: string }>): void => {
      theirPort.postMessage(e.data.type === "loadState" ? { type: "ok" } : { type: "state", state: {} });
    };
    const isState = (msg: object): boolean => (msg as { type?: string }).type === "state";

    await sender({ type: "loadState" }, false);
    const reply = await withDeadline(sender({ type: "requestState" }, true, isState));
    expect(reply).toEqual({ type: "state", state: {} });
    theirPort.close();
  });

  it("does not wait for a reply when `willWait` is false", async () => {
    const [theirPort, sender] = makeCommsChannel();
    await expect(withDeadline(sender({ type: "fire-and-forget" }, false))).resolves.toEqual({});
    theirPort.close();
  });

});
